// UpdateOrg changes an organization with f, which may refuse with an error. A new plan must allow the seats in use
// (otherwise it is a *SeatLimitError).
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	prev := o
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	if o.Plan != prev.Plan {
		if limit, limited := o.Plan.SeatLimit(); limited {
			if used := s.seatsUsedLocked(id); used > limit {
				return Org{}, &SeatLimitError{Limit: limit, Used: used}
			}
		}
	}
	s.orgs[id] = o
	return o, nil
}

// SeatsUsed returns how many seats an organization uses: its members and pending invites whose role is not viewer.
func (s *Store) SeatsUsed(orgID string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.seatsUsedLocked(orgID)
}

// seatsUsedLocked is SeatsUsed for a caller that holds the lock.
func (s *Store) seatsUsedLocked(orgID string) int {
	used := 0
	for k, m := range s.members {
		if k.org == orgID && m.Role != RoleViewer {
			used++
		}
	}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil && inv.Role != RoleViewer {
			used++
		}
	}
	return used
}

// checkSeatLocked returns a *SeatLimitError unless the organization's plan has a free seat for one more. The caller
// holds the lock.
func (s *Store) checkSeatLocked(orgID string) error {
	o, ok := s.orgs[orgID]
	if !ok {
		return ErrNotFound
	}
	limit, limited := o.Plan.SeatLimit()
	if !limited {
		return nil
	}
	if used := s.seatsUsedLocked(orgID); used >= limit {
		return &SeatLimitError{Limit: limit, Used: used}
	}
	return nil
}

