package store

import (
	"errors"
	"sync"
	"sync/atomic"
	"testing"
)

// wantSeatLimit fails the test unless err is a seat limit refusal with these numbers.
func wantSeatLimit(t *testing.T, err error, limit, used int) {
	t.Helper()
	var e *SeatLimitError
	if !errors.As(err, &e) || e.Limit != limit || e.Used != used || !errors.Is(err, ErrConflict) {
		t.Fatalf("err = %v, want a seat limit of %d with %d in use", err, limit, used)
	}
}

func TestSeatLimits(t *testing.T) {
	s := New()
	o, err := s.CreateOrg("Free", OrgFree, "UTC", 0, t0)
	if err != nil {
		t.Fatal(err)
	}
	owner, err := s.CreateUser("owner@free.example", "Owner", t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddMember(o.ID, owner.ID, RoleOwner, t0); err != nil {
		t.Fatal(err)
	}
	invite := func(email string, role Role) (Invite, error) {
		return s.CreateInvite(o.ID, email, role, owner.ID, t0)
	}
	seatsUsed := func(want int) {
		t.Helper()
		if used := s.SeatsUsed(o.ID); used != want {
			t.Fatalf("SeatsUsed = %d, want %d", used, want)
		}
	}

	// The owner holds one of the free plan's three seats.
	ia, err := invite("a@free.example", RoleMember)
	if err != nil {
		t.Fatal(err)
	}
	ib, err := invite("b@free.example", RoleAdmin)
	if err != nil {
		t.Fatal(err)
	}
	_, err = invite("c@free.example", RoleMember)
	wantSeatLimit(t, err, 3, 3)
	if _, err := invite("v@free.example", RoleViewer); err != nil {
		t.Fatalf("a viewer invite needs no seat: %v", err)
	}
	seatsUsed(3)

	// Accepting holds no seat check: the invite already holds one.
	if _, _, _, err := s.AcceptInvite(ia.Token, "A", t0); err != nil {
		t.Fatalf("accept at the limit: %v", err)
	}
	seatsUsed(3)

	// Revoking an invite frees its seat.
	if _, err := s.RevokeInvite(o.ID, ib.ID, t0); err != nil {
		t.Fatal(err)
	}
	seatsUsed(2)
	if _, err := invite("c@free.example", RoleMember); err != nil {
		t.Fatal(err)
	}
	seatsUsed(3)

	// A viewer needs a free seat to become anything else.
	w, err := s.CreateUser("w@free.example", "W", t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddMember(o.ID, w.ID, RoleViewer, t0); err != nil {
		t.Fatal(err)
	}
	_, err = s.SetMemberRole(o.ID, w.ID, RoleMember)
	wantSeatLimit(t, err, 3, 3)
	if m, _ := s.Member(o.ID, w.ID); m.Role != RoleViewer {
		t.Fatalf("role after a refused change = %s", m.Role)
	}
	// Moving a seat holder to viewer frees a seat for the viewer.
	if _, err := s.SetMemberRole(o.ID, "usr_"+ia.Token[:0]+"", RoleViewer); err == nil {
		t.Fatal("a made-up user changed role")
	}
	if _, err := s.SetMemberRole(o.ID, w.ID, RoleViewer); err != nil {
		t.Fatalf("viewer to viewer: %v", err)
	}
	seatsUsed(3)

	// A plan must allow the seats in use.
	if _, err := s.UpdateOrg(o.ID, func(o *Org) error { o.Plan = OrgTeam; return nil }); err != nil {
		t.Fatalf("free to team: %v", err)
	}
	if _, err := invite("d@free.example", RoleMember); err != nil {
		t.Fatalf("team has room: %v", err)
	}
