package api_test

import (
	"net/http"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

type seats struct {
	Used  int  `json:"used"`
	Limit *int `json:"limit"`
}

func TestSeatLimits(t *testing.T) {
	e := apitest.New(t)
	free := e.NewOrg("Free", store.OrgFree, "UTC")
	getSeats := func(key string) seats {
		t.Helper()
		var org struct {
			Seats seats `json:"seats"`
		}
		e.MustDo(http.StatusOK, "GET", "/v1/org", key, nil, &org)
		return org.Seats
	}
	refused := func(r *apitest.Response, status int, code string, limit, used int) {
		t.Helper()
		var body struct {
			Error string `json:"error"`
			Limit int    `json:"limit"`
			Used  int    `json:"used"`
		}
		r.JSON(t, &body)
		if r.Code != status || body.Error != code || body.Limit != limit || body.Used != used {
			t.Fatalf("refusal = %s, want %d %s with limit %d and used %d", r, status, code, limit, used)
		}
	}

	if got := getSeats(free.Key); got.Used != 1 || got.Limit == nil || *got.Limit != 3 {
		t.Fatalf("seats = %+v", got)
	}

	// The owner and two invites use the free plan's three seats; a viewer invite is free.
	var ia, ib store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "a@free.example", "role": "member"}, &ia)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "b@free.example", "role": "admin"}, &ib)
	refused(e.Do("POST", "/v1/invites", free.Key, map[string]string{"email": "c@free.example", "role": "member"}),
		http.StatusPaymentRequired, "seat_limit_reached", 3, 3)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "v@free.example", "role": "viewer"}, nil)

	// Accepting an invite never needs a seat: the invite holds one.
	var accepted struct {
		User store.User `json:"user"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": ia.Token, "name": "A"}, &accepted)
	if got := getSeats(free.Key); got.Used != 3 {
		t.Fatalf("seats after accepting = %+v", got)
	}

	// A revoked invite frees its seat.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+ib.ID, free.Key, nil, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "c@free.example", "role": "member"}, nil)

	// A viewer needs a free seat to become a member, and a seat holder who becomes a viewer frees one.
	w, _ := e.AddMember(free, "w@free.example", store.RoleViewer)
	refused(e.Do("PATCH", "/v1/members/"+w.ID, free.Key, map[string]string{"role": "member"}),
		http.StatusPaymentRequired, "seat_limit_reached", 3, 3)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+accepted.User.ID, free.Key, map[string]string{"role": "viewer"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+w.ID, free.Key, map[string]string{"role": "member"}, nil)
	if got := getSeats(free.Key); got.Used != 3 {
		t.Fatalf("seats after the role changes = %+v", got)
	}

	// A plan change must leave room for the seats in use. Business has no limit.
	for _, email := range []string{"x1@globex.example", "x2@globex.example", "x3@globex.example"} {
		e.AddMember(e.Globex, email, store.RoleMember)
	}
	if got := getSeats(e.Globex.Key); got.Used != 4 || got.Limit != nil {
		t.Fatalf("business seats = %+v", got)
	}
	refused(e.Do("PATCH", "/v1/org", e.Globex.Key, map[string]string{"plan": "free"}),
		http.StatusConflict, "over_seat_limit", 3, 4)
	var org struct {
		Plan store.OrgPlan `json:"plan"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", e.Globex.Key, nil, &org)
	if org.Plan != store.OrgBusiness {
		t.Fatalf("plan after a refused change = %s", org.Plan)
	}
	var changed struct {
		Plan  store.OrgPlan `json:"plan"`
		Seats seats         `json:"seats"`
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Globex.Key, map[string]string{"plan": "team"}, &changed)
	if changed.Plan != store.OrgTeam || changed.Seats.Limit == nil || *changed.Seats.Limit != 10 || changed.Seats.Used != 4 {
		t.Fatalf("after the change = %+v", changed)
	}
}

