368	func (s *Store) APIKeyByToken(token string) (APIKey, bool) {
369		if token == "" {
370			return APIKey{}, false
371		}
372		s.mu.Lock()
373		defer s.mu.Unlock()
374		id, ok := s.keysByToken[token]
375		if !ok {
376			return APIKey{}, false
377		}
378		return s.apiKeys[id], true
379	}
