381	// APIKey returns one of an organization's keys.
382	func (s *Store) APIKey(orgID, id string) (APIKey, bool) {
383		s.mu.Lock()
384		defer s.mu.Unlock()
385		k, ok := s.apiKeys[id]
386		if !ok || k.OrgID != orgID {
387			return APIKey{}, false
388		}
389		return k, true
390	}
