407	func (s *Store) RevokeAPIKey(orgID, id string, now time.Time) (APIKey, error) {
408		s.mu.Lock()
409		defer s.mu.Unlock()
410		k, ok := s.apiKeys[id]
411		if !ok || k.OrgID != orgID {
412			return APIKey{}, ErrNotFound
413		}
414		if k.RevokedAt == nil {
415			t := now.UTC()
416			k.RevokedAt = &t
417			s.apiKeys[id] = k
418		}
419		return k, nil
420	}
