435	// CreateInvite invites an email address to join an organization with a role. An invite for a role other than viewer
436	// holds a seat, so it needs a free one (otherwise it is a *SeatLimitError).
437	func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
438		email = strings.TrimSpace(email)
439		if !validEmail(email) {
440			return Invite{}, invalid("an invite needs a valid email address")
441		}
442		if !role.Valid() || role == RoleOwner {
443			return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
444		}
445		s.mu.Lock()
446		defer s.mu.Unlock()
447		if _, ok := s.orgs[orgID]; !ok {
448			return Invite{}, ErrNotFound
449		}
450		if uid, ok := s.usersByEmail[normEmail(email)]; ok {
451			if _, member := s.members[memberKey{orgID, uid}]; member {
452				return Invite{}, ErrAlreadyMember
453			}
454		}
455		if role != RoleViewer {
456			if err := s.checkSeatLocked(orgID); err != nil {
457				return Invite{}, err
458			}
459		}
460		inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, Token: NewToken("invite_"), InvitedBy: invitedBy, CreatedAt: now.UTC()}
461		s.invites[inv.ID] = inv
462		return inv, nil
463	}
