506	// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
507	// makes them a member with the invite's role and gives them a first API key.
508	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
509		s.mu.Lock()
510		defer s.mu.Unlock()
511		var inv Invite
512		found := false
513		for _, i := range s.invites {
514			if i.Token == token && token != "" {
515				inv, found = i, true
516				break
517			}
518		}
519		if !found || inv.RevokedAt != nil {
520			return User{}, Member{}, APIKey{}, ErrNotFound
521		}
522		var u User
523		if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
524			u = s.users[id]
525		} else {
526			name = strings.TrimSpace(name)
527			if name == "" {
528				return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
529			}
530			u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
531			s.users[u.ID] = u
532			s.usersByEmail[normEmail(u.Email)] = u.ID
533		}
534		m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
535		if err != nil {
536			return User{}, Member{}, APIKey{}, err
537		}
538		k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
539		if err != nil {
540			return User{}, Member{}, APIKey{}, err
541		}
542		t := now.UTC()
543		inv.AcceptedAt = &t
544		s.invites[inv.ID] = inv
545		return u, m, k, nil
546	}
